<?php

/**
 * Re-applies the two Android bridge edits that the Remote Desktop plugin
 * depends on, without touching the rest of the generated NativePHP project.
 *
 * The Android scaffold under nativephp/android is regenerated by
 * `php artisan native:install`. These two edits live in vendor-owned Kotlin
 * files, so they are not tracked by git and are lost whenever the scaffold is
 * recreated. Run this script after every `native:install` and before
 * `native:build android`.
 *
 * Usage:  php nativephp-remote-desktop/patch-android.php [--check]
 *
 * Edits applied:
 *   1. PHPBridge.handleLaravelRequest() gains an overload that accepts an
 *      explicit Cookie header, so a LAN client can use its own session without
 *      being merged into (or overwriting) the phone WebView's cookie store.
 *   2. MainActivity.phpBridge becomes public so plugin bridge functions can
 *      dispatch requests into the same persistent PHP runtime.
 *
 * The script is idempotent: running it twice is a no-op, and --check reports
 * whether the edits are currently applied without writing anything.
 */

$checkOnly = in_array('--check', $argv ?? [], true);

// This file lives at <project>/packages/nativephp-remote-desktop/, so the
// Laravel root is two levels up.
$root = dirname(__DIR__, 2).'/nativephp/android/app/src/main/java/com/nativephp/mobile';

$phpBridge = $root.'/bridge/PHPBridge.kt';
$mainActivity = $root.'/ui/MainActivity.kt';

foreach ([$phpBridge, $mainActivity] as $file) {
    if (! is_file($file)) {
        fwrite(STDERR, "Not found: {$file}\nRun `php artisan native:install` first.\n");
        exit(1);
    }
}

/**
 * Applies a regex-based patch, or reports the current state.
 *
 * Regexes are used instead of literal strings because the generated Kotlin
 * scaffold has unstable line endings and the anchors are whitespace sensitive.
 * Each patch also declares a `$marker`: a substring that is present only once
 * the patch has been applied, which is what makes re-running this a no-op.
 */
function applyPatch(string $file, string $pattern, string $replacement, string $marker, string $label, bool $checkOnly): bool
{
    $contents = file_get_contents($file);
    $crlf = str_contains($contents, "\r\n");
    $haystack = $crlf ? str_replace("\r\n", "\n", $contents) : $contents;

    if (str_contains($haystack, $marker)) {
        echo "  [ok]      {$label} (already applied)\n";

        return true;
    }

    $patched = preg_replace($pattern, $replacement, $haystack, 1, $count);

    if ($count === 0 || $patched === null) {
        if ($checkOnly) {
            echo "  [MISSING] {$label} (not applied)\n";

            return false;
        }
        fwrite(STDERR, "  [FAILED]  {$label}\n");
        fwrite(STDERR, "            The NativePHP template changed; re-check the patch manually.\n");

        return false;
    }

    if ($checkOnly) {
        echo "  [MISSING] {$label} (patchable, not applied)\n";

        return false;
    }

    if ($crlf) {
        $patched = str_replace("\n", "\r\n", $patched);
    }
    file_put_contents($file, $patched);
    echo "  [patched] {$label}\n";

    return true;
}

$overloadMarker = 'fun handleLaravelRequest(request: PHPRequest, explicitCookieHeader: String?): String';
$cookieMarker = 'explicitCookieHeader ?: LaravelCookieStore.asCookieHeader()';
$visibilityMarker = '    val phpBridge by lazy';

echo $checkOnly
    ? "Checking NativePHP Android bridge patches:\n"
    : "Applying NativePHP Android bridge patches:\n";

$ok = true;

// 1. PHPBridge: an overload that dispatches with an explicit cookie header, so
//    a LAN client keeps its own session instead of sharing the phone's store.
$ok = applyPatch(
    $phpBridge,
    '/(    fun handleLaravelRequest\(request: PHPRequest\): String \{)/',
    <<<'KT'
    fun handleLaravelRequest(request: PHPRequest): String {
        return handleLaravelRequest(request, null)
    }

    /**
     * Dispatch an HTTP request while optionally using an isolated cookie header.
     * Remote/LAN clients pass their own session cookie; normal WebView calls pass
     * null and retain the shared WebView cookie jar behavior.
     */
    fun handleLaravelRequest(request: PHPRequest, explicitCookieHeader: String?): String {
KT,
    $overloadMarker,
    'PHPBridge.handleLaravelRequest overload',
    $checkOnly
) && $ok;

// 2. PHPBridge: honour the explicit cookie header when one is supplied.
$ok = applyPatch(
    $phpBridge,
    '/            val cookieHeader = LaravelCookieStore\.asCookieHeader\(\)/',
    '            val cookieHeader = explicitCookieHeader ?: LaravelCookieStore.asCookieHeader()',
    $cookieMarker,
    'PHPBridge explicit cookie header',
    $checkOnly
) && $ok;

// 3. MainActivity: expose phpBridge so plugin bridge functions can dispatch.
$ok = applyPatch(
    $mainActivity,
    '/    private val phpBridge by lazy \{ PHPBridge\(this\) \}/',
    '    val phpBridge by lazy { PHPBridge(this) }',
    $visibilityMarker,
    'MainActivity.phpBridge visibility',
    $checkOnly
) && $ok;

if ($checkOnly) {
    exit($ok ? 0 : 1);
}

if ($ok) {
    echo "Done. You can now run: php artisan native:build android\n";
    exit(0);
}

fwrite(STDERR, "\nSome patches could not be applied. The NativePHP Android template may have changed.\n");
exit(1);
